interface Service { Result op(Request r); }        // client-facing contract
class Delegate implements Service {
    private ServiceHandle handle;                    // lookup cache
    public Result op(Request r) {
        if (handle == null) handle = lookup.resolve(serviceId());
        try { return transport.invoke(handle, r); }
        catch (TransportError e) { handle = null; throw new AppError("unavailable", e); }
    }
}
